-- Create "hints" table
CREATE TABLE "hints" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "user_id" character varying NOT NULL, "text" text NOT NULL, "status" character varying NOT NULL, "model" character varying NULL, "created_at" timestamptz NOT NULL, "submission_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "hints_submissions_hint" FOREIGN KEY ("submission_id") REFERENCES "submissions" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "hint_user_id_created_at" to table: "hints"
CREATE INDEX "hint_user_id_created_at" ON "hints" ("user_id", "created_at");
-- Create index "hints_submission_id_key" to table: "hints"
CREATE UNIQUE INDEX "hints_submission_id_key" ON "hints" ("submission_id");
